        Added the ``call`` parameter.
    """
    value = ctx.lookup_default(self.name, call=False)  # type: ignore

    if value is None:
        value = self.default

    if callable(value):
        if not call:
            # Don't type cast the callable.
            return value

        value = value()

    try:
        return self.type_cast_value(ctx, value)
    except BadParameter:
        if ctx.resilient_parsing:
            return value

        raise

